    for i in 1..values.len() {
        let value = values[i].clone();
        let mut j = i;
        // A strict comparison leaves an equal earlier key in front.
        while j > 0 && key(&values[j - 1]) > key(&value) {
            values[j] = values[j - 1].clone();
            j -= 1;
        }
        values[j] = value;
    }
