fn counting_sort(values: &[usize], maximum: usize) -> Vec<usize> {
    let mut counts = vec![0; maximum + 1];
    for &x in values {
        counts[x] += 1;
    }
    let mut out = Vec::with_capacity(values.len());
    for (x, &count) in counts.iter().enumerate() {
        out.extend(std::iter::repeat_n(x, count));
    }
    out
}

