fn partition_list(mut head: Link, pivot: i32) -> Link {
    let (mut low, mut high) = (None, None);
    let (mut a, mut b) = (&mut low, &mut high);
    while let Some(mut node) = head {
        head = node.next.take();
        if node.value < pivot {
            *a = Some(node);
            a = &mut a.as_mut().unwrap().next;
        } else {
            *b = Some(node);
            b = &mut b.as_mut().unwrap().next;
        }
    }
    *a = high;
    low
}

fn main() {
    let result = csv(list_values(&partition_list(list(&[1, 4, 3, 2, 5, 2]), 3)));
    println!("{result}");
}

