fn dfs_order(graph: &[Vec<usize>], start: usize) -> Vec<usize> {
    fn visit(v: usize, g: &[Vec<usize>], seen: &mut [bool], out: &mut Vec<usize>) {
        seen[v] = true;
        out.push(v);
        for &u in &g[v] {
            if !seen[u] {
                visit(u, g, seen, out);
            }
        }
    }
    let mut sorted = graph.to_vec();
    for ns in &mut sorted {
        ns.sort_unstable();
    }
    let mut out = Vec::new();
    visit(start, &sorted, &mut vec![false; graph.len()], &mut out);
    out
}

