fn edge_distances(graph: &[Vec<usize>], start: usize) -> Vec<i32> {
    let mut distance = vec![-1; graph.len()];
    let mut queue = std::collections::VecDeque::from([start]);
    distance[start] = 0;
    while let Some(v) = queue.pop_front() {
        for &u in &graph[v] {
            if distance[u] == -1 {
                distance[u] = distance[v] + 1;
                queue.push_back(u);
            }
        }
    }
    distance
}

