    for (deadline, value) in sorted {
        if value <= 0 {
            continue;
        }
        let slot = free(&mut parent, deadline.min(n));
        if slot > 0 {
            profit += value;
            parent[slot] = free(&mut parent, slot - 1);
        }
    }
    profit
}

