        g: &[Vec<usize>],
        parent: &mut [usize],
        depth: &mut [usize],
        size: &mut [usize],
        heavy: &mut [usize],
    ) {
        parent[v] = p;
        size[v] = 1;
        for &u in &g[v] {
            if u != p {
                depth[u] = depth[v] + 1;
                sizes(u, v, g, parent, depth, size, heavy);
                size[v] += size[u];
                if heavy[v] == g.len() || size[u] > size[heavy[v]] {
                    heavy[v] = u;
                }
            }
        }
    }
    fn split(
        v: usize,
        h: usize,
        g: &[Vec<usize>],
        parent: &[usize],
        heavy: &[usize],
        head: &mut [usize],
        position: &mut [usize],
        timer: &mut usize,
    ) {
        head[v] = h;
        position[v] = *timer;
        *timer += 1;
        if heavy[v] != g.len() {
            split(heavy[v], h, g, parent, heavy, head, position, timer);
        }
        for &u in &g[v] {
            if u != parent[v] && u != heavy[v] {
                split(u, u, g, parent, heavy, head, position, timer);
            }
        }
    }
    let n = graph.len();
