    };
    let mut sum = 0;
    while head[a] != head[b] {
        if depth[head[a]] < depth[head[b]] {
            std::mem::swap(&mut a, &mut b);
        }
        sum += prefix(position[a] + 1) - prefix(position[head[a]]);
        a = parent[head[a]];
    }
    let (left, right) = (position[a].min(position[b]), position[a].max(position[b]));
    sum + prefix(right + 1) - prefix(left)
}

