    fn collect(
        v: usize,
        p: usize,
        g: &[Vec<usize>],
        blocked: &[bool],
        sizes: &mut [usize],
        members: &mut Vec<usize>,
    ) {
        sizes[v] = 1;
        members.push(v);
        for &u in &g[v] {
            if u != p && !blocked[u] {
                collect(u, v, g, blocked, sizes, members);
                sizes[v] += sizes[u];
            }
        }
    }
    fn decompose(
        start: usize,
        parent: Option<usize>,
        g: &[Vec<usize>],
        blocked: &mut [bool],
        answer: &mut [Option<usize>],
        sizes: &mut [usize],
